import fractions as f, sys
(N, Q) = list(map(int, sys.stdin.readline().split()))
A = sorted(map(int, sys.stdin.readline().split()))
if N == 1:
	print(A[0])
else:
	common_gcd = A[1] - A[0]
	for i in range(1, N):
		A[i] -= A[0]
		common_gcd = f.gcd(common_gcd, A[i])
	for _ in range(Q):
		K = int(sys.stdin.readline())
		print(f.gcd(A[0] + K, common_gcd))
